            var errΔ1 = h2._<encoding.BinaryUnmarshaler>().UnmarshalBinary(state); if (errΔ1 != default!) {
                Ꮡt.Errorf("could not unmarshal: %v"u8, errΔ1);
                continue;
            }
        }
        io.WriteString(h, g.@in.slice(len(g.@in) / 2));
        io.WriteString(h2, g.@in.slice(len(g.@in) / 2));
        {
