internal static (slice<byte> sum, error err) safeSum(hash.Hash h) {
    slice<byte> sum = default!;
    error err = default!;
    GoFrame ᒐ = default;
    try {
        defer(() => {
            {
                var r = recover(); if (r != default!) {
                    err = fmt.Errorf("sum panic: %v"u8, r);
                }
            }
        }, ref ᒐ);
        (sum, err) = (h.Sum(default!), default!);
    }
    catch (Exception ᒐex) when (GoFrame.IsPanic(ᒐex, out PanicException? ᒐp)) { GoFrame.Capture(ᒐp); }
    finally { ᒐ.Run(); }
    return (sum, err);
}

public static void TestLargeHashes(ж<testing.T> Ꮡt) {
    foreach (var (i, test) in largeUnmarshalTests) {
        var h = New();
        {
            var errΔ1 = h._<encoding.BinaryUnmarshaler>().UnmarshalBinary(slice<byte>(test.state)); if (errΔ1 != default!) {
                Ꮡt.Errorf("test %d could not unmarshal: %v"u8, i, errΔ1);
                continue;
            }
        }
        var (sum, err) = safeSum(h);
        if (err != default!) {
            Ꮡt.Errorf("test %d could not sum: %v"u8, i, err);
            continue;
        }
        if (fmt.Sprintf("%x"u8, sum) != test.sum) {
            Ꮡt.Errorf("test %d sum mismatch: expect %s got %x"u8, i, test.sum, sum);
        }
    }
}

